export function create_scopes(expression: Node) {
	const map = new WeakMap();

	const globals: Map<string, Node> = new Map();
	let scope = new Scope(null, false);

	walk(expression, {
		enter(node, parent) {
			if (node.type === 'ImportDeclaration') {
				node.specifiers.forEach(specifier => {
